import heapq

def clearStars(s: str) -> str:
    n = len(s)
    removed = [False] * n
    heap = []  # (char, -index): smallest char first, and rightmost index among equal chars

    for i, ch in enumerate(s):
        if ch == '*':
            _, neg_idx = heapq.heappop(heap)
            removed[-neg_idx] = True   # delete the chosen letter
            removed[i] = True          # delete the star
        else:
            heapq.heappush(heap, (ch, -i))

    return ''.join(ch for i, ch in enumerate(s) if not removed[i])
